package com.pricetrack.exchange.custody.authorization;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.pricetrack.exchange.custody.abi.CAbiModels.Intent;
import com.pricetrack.exchange.custody.proof.CEip712Verifier;
import com.pricetrack.exchange.custody.runtime.*;
import com.pricetrack.exchange.custody.runtime.CCustodyRpcReader.*;
import com.pricetrack.exchange.futures.ledger.FuturesLedger;
import com.pricetrack.exchange.futures.math.FuturesMath;
import com.pricetrack.exchange.market.*;
import com.pricetrack.exchange.market.model.*;
import com.pricetrack.exchange.market.provider.MarketPriceProvider;
import java.math.*;
import java.time.*;
import java.util.*;
import java.util.function.*;
import org.junit.jupiter.api.Test;
import org.web3j.crypto.Hash;
import static com.pricetrack.exchange.custody.authorization.CConsentModelsTest.*;
import static org.junit.jupiter.api.Assertions.*;

/** Pure candidate tests: real product market gate and fake provider/prestate, no signing/DB/RPC sockets. */
public class CReportCandidateBuilderTest {
    static final BigInteger E8=BigInteger.TEN.pow(8);
    static final class Time extends Clock {Instant value=NOW;public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return value;}}
    static final class Provider implements MarketPriceProvider {
        final Time time;BigDecimal price=new BigDecimal("100");String symbol="mSEC",name="SIMULATED";Long generation=1L;
        long age;boolean allowed=true;MarketStatus status=MarketStatus.OPEN;PriceStatus priceStatus=PriceStatus.SIMULATED;int calls;IntConsumer onRead=n->{};
        Provider(Time time){this.time=time;}
        public MarketPriceSnapshot current(){return new MarketPriceSnapshot(symbol,price,new BigDecimal("100"),BigDecimal.ZERO,BigDecimal.ZERO,status,priceStatus,name,time.value.minusSeconds(age));}
        @Override public TradingPriceContext currentForTrading(){onRead.accept(++calls);return new TradingPriceContext(current(),allowed,"CONTROLLED_FIXTURE",generation);}
    }
    static CCustodyIdentity configured(){var c=identity();return new CCustodyIdentity(c.chainId(),c.genesisHash(),c.token(),c.controller(),c.rules(),c.vault(),c.relayer(),c.oracle(),c.pauseAdmin(),Hash.sha3String("mSEC"),c.policyHash(),c.origin());}
    static Intent open(){var i=intent();i=change(i,"symbolHash",configured().symbolHash());i=change(i,"accountRef",CConsentModels.accountRef(OWNER,configured().symbolHash()));i=change(i,"priceMinE8",E8.multiply(BigInteger.valueOf(90)));i=change(i,"priceMaxE8",E8.multiply(BigInteger.valueOf(110)));i=change(i,"quantityMin",BigInteger.valueOf(90));return change(i,"quantityMax",BigInteger.valueOf(110));}
    static Intent existing(int action){var i=open();i=change(i,"action",BigInteger.valueOf(action));i=change(i,"expectedVersion",BigInteger.valueOf(2));i=change(i,"expectedCallEpoch",BigInteger.ONE);i=change(i,"entryPriceE8",E8.multiply(BigInteger.valueOf(100)));i=change(i,"collateralBefore",BigInteger.valueOf(1000));i=change(i,"collateralAfter",BigInteger.valueOf(action==1?1200:1000));i=change(i,"quantityMin",BigInteger.valueOf(100));return change(i,"quantityMax",BigInteger.valueOf(100));}
    static Observation<AdmissionPrestate> observation(Intent i,Instant now){boolean open=i.action().signum()==0;
        PositionView p=open?new PositionView(i.positionId(),addr(0),hash(0),"0","0","0","0","0","NONE","0","0","0","0","0",false)
            :new PositionView(i.positionId(),i.owner(),i.accountRef(),i.side().toString(),i.leverage().toString(),"100",E8.multiply(BigInteger.valueOf(100)).toString(),"1000","ACTIVE","2","1","0",Long.toString(now.minusSeconds(10).getEpochSecond()),"1000",false);
        return new Observation<>(configured().deploymentId(),new Point("100",hash(100),hash(99),Long.toString(now.getEpochSecond())),now,
            new AdmissionPrestate(i,i.nonce().toString(),"10000",open?"0":"1000","0",false,open?hash(0):i.positionId(),p));
    }
    static final class Fixture {
        final Time time=new Time();final Provider provider=new Provider(time);Function<Intent,Observation<AdmissionPrestate>> read=i->observation(i,time.value);
        CReportCandidateBuilder builder(){return new CReportCandidateBuilder(configured(),i->read.apply(i),new MarketPriceService(provider),time,"mSEC");}
    }
    static String code(Runnable r){return assertThrows(CCustodyFailure.class,r::run).code();}
    @Test void openIsExactUnsignedCandidateWithSeparatePriceDomain()throws Exception{
        var f=new Fixture();var i=open();var c=f.builder().build(i);var r=c.report();assertEquals(BigInteger.valueOf(100),r.quantity());assertEquals(E8.multiply(BigInteger.valueOf(100)),r.priceE8());assertEquals(r.priceE8(),r.entryPriceE8());
        assertEquals(i.operationId(),r.operationId());assertEquals(i.positionId(),r.positionId());assertEquals(i.accountRef(),r.accountRef());assertEquals(i.symbolHash(),r.symbolHash());assertEquals(i.policyHash(),r.policyHash());assertEquals(i.collateralAfter(),r.collateralAfter());assertEquals(i.expectedVersion(),r.expectedVersion());assertEquals(i.expectedCallEpoch(),r.expectedCallEpoch());assertEquals(i.side(),r.side());assertEquals(i.leverage(),r.leverage());
        assertEquals(configured().controller().address(),r.executor());assertEquals(BigInteger.valueOf(30),r.validUntil().subtract(r.observedAt()));var crypto=new CEip712Verifier();assertEquals(crypto.reportDigest(r,configured().chainId(),configured().rules().address()),c.reportDigest());assertNotEquals(crypto.reportDigest(r,configured().chainId(),configured().controller().address()),c.reportDigest());
        assertEquals(CReportCandidateBuilder.SCOPE,c.scope());assertFalse(c.calculatedMark().atRisk());var json=new ObjectMapper().registerModule(new com.fasterxml.jackson.datatype.jsr310.JavaTimeModule());var tree=json.readTree(json.writeValueAsString(c));assertEquals(CReportCandidateBuilder.SCOPE,tree.get("scope").asText());assertFalse(tree.has("priceSignature"));assertFalse(tree.has("raw"));assertFalse(tree.has("paidProfit"));assertFalse(tree.has("createdUnpaid"));assertEquals(i,open());
        for(int side:List.of(0,1))for(int leverage:List.of(2,5,10)){var v=change(i,"side",BigInteger.valueOf(side));v=change(v,"leverage",BigInteger.valueOf(leverage));v=change(v,"quantityMin",BigInteger.ONE);v=change(v,"quantityMax",BigInteger.valueOf(200));var candidate=f.builder().build(v);assertEquals(BigInteger.valueOf(leverage*10L),candidate.report().quantity());assertEquals(BigInteger.valueOf(side),candidate.report().side());}
    }
    @Test void selectsNewMarketPriceAfterDelayedUserApprovalAndRpc(){var f=new Fixture();var i=open();f.read=v->{f.time.value=NOW.plusSeconds(10);f.provider.price=new BigDecimal("101");return observation(v,f.time.value);};var c=f.builder().build(i);assertEquals(E8.multiply(BigInteger.valueOf(101)),c.report().priceE8());assertEquals(BigInteger.valueOf(99),c.report().quantity());assertEquals(BigInteger.valueOf(NOW.plusSeconds(10).getEpochSecond()),c.report().observedAt());assertEquals(i,c.prestate().value().intent());}
    @Test void topUpAndCloseRetainExactEntryQuantityAndOnlyPredictPnl(){for(int action:List.of(1,4)){var f=new Fixture();f.provider.price=new BigDecimal("95");var i=existing(action);var c=f.builder().build(i);assertEquals(i.entryPriceE8(),c.report().entryPriceE8());assertEquals(BigInteger.valueOf(100),c.report().quantity());assertEquals(i.collateralBefore(),c.report().collateralBefore());assertEquals(i.collateralAfter(),c.report().collateralAfter());assertEquals(BigInteger.valueOf(-500),c.calculatedMark().unrealized());assertEquals(BigInteger.valueOf(action==1?700:500),c.calculatedMark().equity());}}
    @Test void explicitPriceBoundsIncludeEdgesAndRejectOutside(){for(String p:List.of("90","110")){var f=new Fixture();f.provider.price=new BigDecimal(p);var i=change(open(),"quantityMin",BigInteger.ONE);i=change(i,"quantityMax",BigInteger.valueOf(200));assertEquals(new BigDecimal(p).movePointRight(8).toBigIntegerExact(),f.builder().build(i).report().priceE8());}for(String p:List.of("89.99999999","110.00000001")){var f=new Fixture();f.provider.price=new BigDecimal(p);assertEquals("C_REPORT_CANDIDATE_PRICE_BOUNDS",code(()->f.builder().build(open())));}}
    @Test void executionQuantityAlwaysUsesExistingFloorFormulaAndSignedBounds(){var f=new Fixture();f.provider.price=new BigDecimal("99");var i=change(open(),"quantityMin",BigInteger.valueOf(100));i=change(i,"quantityMax",BigInteger.valueOf(100));Intent fixed=i;assertEquals("C_REPORT_CANDIDATE_QUANTITY_BOUNDS",code(()->f.builder().build(fixed)));var c=f.builder().build(open());assertEquals(FuturesMath.quantity(c.report().collateralAfter(),10,c.report().priceE8()),c.report().quantity());assertEquals(BigInteger.valueOf(101),c.report().quantity());
        var tiny=new Fixture();tiny.provider.price=BigDecimal.ONE;var risky=change(open(),"collateralAfter",BigInteger.ONE);risky=change(risky,"priceMinE8",E8);risky=change(risky,"priceMaxE8",E8.multiply(BigInteger.TWO));risky=change(risky,"quantityMin",BigInteger.ONE);risky=change(risky,"quantityMax",BigInteger.valueOf(20));Intent riskIntent=risky;assertEquals("C_RULES_OPEN_RISK",assertThrows(IllegalArgumentException.class,()->tiny.builder().build(riskIntent)).getMessage());}
    @Test void fiveSecondAndTwoSecondFutureBoundariesRemainUnchanged(){for(long age:new long[]{5,-2}){var f=new Fixture();f.provider.age=age;assertNotNull(f.builder().build(open()));}for(long age:new long[]{6,-3}){var f=new Fixture();f.provider.age=age;assertEquals("MARKET_UNAVAILABLE",assertThrows(FuturesLedger.Failure.class,()->f.builder().build(open())).getMessage());}}
    @Test void tickProviderOrGenerationChangeRejectsWithoutAutomaticRefresh(){for(String field:List.of("tick","provider","generation")){var f=new Fixture();f.provider.onRead=n->{if(n==2){if(field.equals("tick"))f.provider.price=new BigDecimal("101");if(field.equals("provider"))f.provider.name="OTHER";if(field.equals("generation"))f.provider.generation=2L;}};assertEquals(field.equals("tick")?"PRICE_CHANGED":"MARKET_CONNECTION_CHANGED",assertThrows(FuturesLedger.Failure.class,()->f.builder().build(open())).getMessage());assertEquals(2,f.provider.calls);}
        for(String field:List.of("tick","provider","generation","stale")){var f=new Fixture();var builder=f.builder();var fixed=builder.build(open());if(field.equals("tick"))f.provider.price=new BigDecimal("101");if(field.equals("provider"))f.provider.name="OTHER";if(field.equals("generation"))f.provider.generation=2L;if(field.equals("stale"))f.time.value=NOW.plusSeconds(6);assertEquals(field.equals("tick")?"PRICE_CHANGED":field.equals("stale")?"MARKET_UNAVAILABLE":"MARKET_CONNECTION_CHANGED",assertThrows(FuturesLedger.Failure.class,()->builder.revalidate(fixed)).getMessage());}}
    @Test void samePriceNewTickDoesNotInvalidateCandidate(){var f=new Fixture();f.provider.age=1;f.provider.onRead=n->{if(n==2)f.provider.age=0;};var builder=f.builder();var c=builder.build(open());assertEquals(BigInteger.valueOf(NOW.minusSeconds(1).getEpochSecond()),c.report().observedAt());assertEquals(2,f.provider.calls);builder.revalidate(c);assertEquals(3,f.provider.calls);var tampered=new CReportCandidateBuilder.Candidate(c.report(),hash(999),c.market(),c.prestate(),c.calculatedMark());assertEquals("C_REPORT_CANDIDATE_CANDIDATE_SCOPE",code(()->builder.revalidate(tampered)));}
    @Test void closedStaleDisallowedAndNonE8PriceRemainRejected(){for(String reason:List.of("closed","stale","disallowed","precision")){var f=new Fixture();if(reason.equals("closed"))f.provider.status=MarketStatus.CLOSED;if(reason.equals("stale"))f.provider.priceStatus=PriceStatus.STALE;if(reason.equals("disallowed"))f.provider.allowed=false;if(reason.equals("precision"))f.provider.price=new BigDecimal("100.000000001");assertEquals(reason.equals("precision")?"INVALID_MARK_PRICE":"MARKET_UNAVAILABLE",assertThrows(FuturesLedger.Failure.class,()->f.builder().build(open())).getMessage());}}
    @Test void marketSymbolMustBeExplicitlyBoundToCDeployment(){var f=new Fixture();assertEquals("C_REPORT_CANDIDATE_SYMBOL_BINDING",code(()->new CReportCandidateBuilder(configured(),i->observation(i,NOW),new MarketPriceService(f.provider),f.time,"OTHER")));f.provider.symbol="OTHER";assertEquals("MARKET_UNAVAILABLE",assertThrows(FuturesLedger.Failure.class,()->f.builder().build(open())).getMessage());}
    @Test void staleOrWrongPrestateAndWindowCannotBecomeCandidate(){var f=new Fixture();var i=open();f.read=v->{var o=observation(v,NOW);return new Observation<>("0".repeat(64),o.block(),o.observedAt(),o.value());};assertEquals("C_REPORT_CANDIDATE_PRESTATE_SCOPE",code(()->f.builder().build(i)));f.read=v->observation(v,NOW.minusSeconds(15));assertEquals("C_REPORT_CANDIDATE_PRESTATE_EXPIRED",code(()->f.builder().build(i)));f.time.value=NOW.plusSeconds(121);assertEquals("C_CONSENT_INTENT_WINDOW",code(()->f.builder().build(i)));}
    @Test void elapsedTimeAndClockRollbackAreCheckedAfterFinalMarketValidation(){var f=new Fixture();f.provider.onRead=n->{if(n==2)f.time.value=NOW.plusSeconds(121);};assertEquals("MARKET_UNAVAILABLE",assertThrows(FuturesLedger.Failure.class,()->f.builder().build(open())).getMessage());var back=new Fixture();back.time.value=NOW.plusSeconds(1);back.provider.onRead=n->{if(n==2)back.time.value=NOW;};assertEquals("C_REPORT_CANDIDATE_PRESTATE_EXPIRED",code(()->back.builder().build(open())));}
    @Test void reportAndUserWindowsAreIndependentAndBadStateFailsRules(){var f=new Fixture();f.read=i->{var o=observation(i,NOW);return new Observation<>(o.deploymentId(),new Point("100",hash(100),hash(99),Long.toString(NOW.plusSeconds(31).getEpochSecond())),NOW,o.value());};assertEquals("C_RULES_REPORT_TIME",assertThrows(IllegalArgumentException.class,()->f.builder().build(open())).getMessage());var g=new Fixture();g.read=i->{var o=observation(i,NOW);var p=o.value().position();var bad=new PositionView(p.positionId(),p.owner(),p.accountRef(),p.side(),p.leverage(),p.quantity(),p.entryPriceE8(),p.historicalCollateral(),p.status(),"3",p.callEpoch(),p.deadline(),p.lastObservedAt(),p.lockedCollateral(),p.lockTerminal());return new Observation<>(o.deploymentId(),o.block(),o.observedAt(),new AdmissionPrestate(i,o.value().userNonce(),o.value().free(),o.value().locked(),"0",false,o.value().activePosition(),bad));};assertEquals("C_RULES_VERSION_EPOCH",assertThrows(IllegalArgumentException.class,()->g.builder().build(existing(4))).getMessage());}
    @Test void onlyPublicConstructionUsesFixedReaderAndNoSigningOrDispatchExists(){assertEquals(1,CReportCandidateBuilder.class.getConstructors().length);assertArrayEquals(new Class<?>[]{CCustodyRpcReader.class,MarketPriceService.class,Clock.class,String.class},CReportCandidateBuilder.class.getConstructors()[0].getParameterTypes());assertTrue(Arrays.stream(CReportCandidateBuilder.class.getDeclaredMethods()).noneMatch(m->Set.of("sign","send","submit","reprice","saveSigned").contains(m.getName())));}
}
